/* =========================================================
   Hemalatha G — Portfolio, Style 3: Aurora glass
   ========================================================= */
(() => {
  "use strict";
  const $ = (s, c = document) => c.querySelector(s);
  const $$ = (s, c = document) => Array.from(c.querySelectorAll(s));
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const fine = matchMedia("(hover: hover) and (pointer: fine)").matches;

  /* ---------- Toast ---------- */
  const toast = $(".toast"); let tt;
  const say = (m) => { toast.textContent = m; toast.classList.add("on"); clearTimeout(tt); tt = setTimeout(() => toast.classList.remove("on"), 2600); };

  /* ---------- Resume download (embedded PDF) ---------- */
  const downloadResume = () => {
    try {
      const bin = atob(window.RESUME_PDF_B64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      const url = URL.createObjectURL(new Blob([bytes], { type: "application/pdf" }));
      const a = Object.assign(document.createElement("a"), { href: url, download: "Hemalatha_G_Resume.pdf" });
      a.style.display = "none"; document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 10000);
      say("Resume downloaded");
    } catch { location.href = "Hemalatha_G_Resume.pdf"; }
  };
  $$("[data-download]").forEach((el) => el.addEventListener("click", (e) => { e.preventDefault(); downloadResume(); }));
  $("#copy-email").addEventListener("click", async () => {
    const email = "hemalathagobalakrishnan@gmail.com";
    try { await navigator.clipboard.writeText(email); say("Email copied"); } catch { say(email); }
  });
  $("#year").textContent = new Date().getFullYear();

  /* ---------- WhatsApp enquiry ---------- */
  const WA_NUMBER = "917708743907";
  const waForm = $("#wa-form");
  const waError = $(".wa-error", waForm);
  const waField = (n) => waForm.elements.namedItem(n);
  waForm.addEventListener("submit", (e) => {
    e.preventDefault();
    const [nameEl, companyEl, messageEl] = ["name", "company", "message"].map(waField);
    const name = nameEl.value.trim(), company = companyEl.value.trim(), message = messageEl.value.trim();
    nameEl.setAttribute("aria-invalid", String(!name));
    messageEl.setAttribute("aria-invalid", String(!message));
    if (!name || !message) { waError.hidden = false; (name ? messageEl : nameEl).focus(); return; }
    waError.hidden = true;
    const text = `Hi Hemalatha, this is ${name}${company ? ` from ${company}` : ""}.\n\n${message}`;
    window.open(`https://wa.me/${WA_NUMBER}?text=${encodeURIComponent(text)}`, "_blank", "noopener");
    say("Opening WhatsApp…");
  });
  $$("input, textarea", waForm).forEach((f) => f.addEventListener("input", () => { f.removeAttribute("aria-invalid"); waError.hidden = true; }));

  /* ---------- Menu ---------- */
  const burger = $(".burger"), menu = $("#menu");
  const setMenu = (open) => {
    burger.setAttribute("aria-expanded", String(open));
    burger.setAttribute("aria-label", open ? "Close menu" : "Open menu");
    menu.hidden = !open; document.body.classList.toggle("locked", open);
  };
  burger.addEventListener("click", () => setMenu(menu.hidden));
  $$("a", menu).forEach((a) => a.addEventListener("click", () => setMenu(false)));
  addEventListener("keydown", (e) => { if (e.key === "Escape" && !menu.hidden) setMenu(false); });

  const links = $$(".links a");
  const navIO = new IntersectionObserver((en) => en.forEach((e) => {
    if (e.isIntersecting) links.forEach((l) => l.classList.toggle("current", l.getAttribute("href") === "#" + e.target.id));
  }), { rootMargin: "-45% 0px -50% 0px" });
  $$("section[id]").forEach((s) => navIO.observe(s));

  /* ---------- Hero intro + reveals ---------- */
  requestAnimationFrame(() => setTimeout(() => document.body.classList.add("loaded"), 150));
  const rio = new IntersectionObserver((en) => {
    en.filter((e) => e.isIntersecting).forEach((e, i) => {
      e.target.style.setProperty("--d", `${i * .1}s`); e.target.classList.add("in"); rio.unobserve(e.target);
    });
  }, { threshold: .15 });
  $$(".reveal").forEach((el) => rio.observe(el));

  /* ---------- Skill deck: fans out when it scrolls in ---------- */
  const deck = $("#deck");
  const cards = $$(".scard", deck);
  if (!reduce) {
    deck.classList.add("stacked");
    new IntersectionObserver(([e], o) => {
      if (!e.isIntersecting) return;
      o.disconnect();
      setTimeout(() => deck.classList.remove("stacked"), 150);
    }, { threshold: .35 }).observe(deck);
  }
  const setActive = (c) => cards.forEach((x) => x.classList.toggle("active", x === c));
  cards.forEach((c) => {
    if (fine) c.addEventListener("mouseenter", () => setActive(c));
    c.addEventListener("focus", () => setActive(c));
    c.addEventListener("click", () => setActive(c.classList.contains("active") ? null : c));
  });
  if (fine) deck.addEventListener("mouseleave", () => setActive(null));

  /* ---------- Experience: stacking cards scale back ---------- */
  const xcards = $$(".xcard");
  const stackTick = () => {
    xcards.forEach((card, i) => {
      const next = xcards[i + 1];
      if (!next || reduce) { card.style.transform = ""; return; }
      const a = card.getBoundingClientRect(), b = next.getBoundingClientRect();
      const overlap = Math.min(Math.max((a.bottom - b.top) / a.height, 0), 1);
      card.style.transform = `scale(${1 - overlap * .06})`;
      card.style.filter = `saturate(${1 - overlap * .4}) brightness(${1 - overlap * .06})`;
    });
  };
  addEventListener("scroll", () => requestAnimationFrame(stackTick), { passive: true });
  stackTick();

  /* ---------- 3D iridescent glass blob ---------- */
  const canvas = $("#blob");
  if (!window.THREE || !canvas) return;
  let renderer;
  try { renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true }); } catch { return; }
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(35, 1, .1, 100);
  camera.position.z = 6.2;

  const uniforms = { uTime: { value: 0 }, uAmp: { value: .32 }, uMouse: { value: new THREE.Vector2() }, uHover: { value: 0 } };
  const noise = `
    vec3 mod289(vec3 x){return x-floor(x*(1./289.))*289.;}
    vec4 mod289(vec4 x){return x-floor(x*(1./289.))*289.;}
    vec4 permute(vec4 x){return mod289(((x*34.)+1.)*x);}
    vec4 taylorInvSqrt(vec4 r){return 1.79284291400159-.85373472095314*r;}
    float snoise(vec3 v){
      const vec2 C=vec2(1./6.,1./3.); const vec4 D=vec4(0.,.5,1.,2.);
      vec3 i=floor(v+dot(v,C.yyy)); vec3 x0=v-i+dot(i,C.xxx);
      vec3 g=step(x0.yzx,x0.xyz); vec3 l=1.-g; vec3 i1=min(g.xyz,l.zxy); vec3 i2=max(g.xyz,l.zxy);
      vec3 x1=x0-i1+C.xxx; vec3 x2=x0-i2+C.yyy; vec3 x3=x0-D.yyy;
      i=mod289(i);
      vec4 p=permute(permute(permute(i.z+vec4(0.,i1.z,i2.z,1.))+i.y+vec4(0.,i1.y,i2.y,1.))+i.x+vec4(0.,i1.x,i2.x,1.));
      float n_=.142857142857; vec3 ns=n_*D.wyz-D.xzx;
      vec4 j=p-49.*floor(p*ns.z*ns.z); vec4 x_=floor(j*ns.z); vec4 y_=floor(j-7.*x_);
      vec4 x=x_*ns.x+ns.yyyy; vec4 y=y_*ns.x+ns.yyyy; vec4 h=1.-abs(x)-abs(y);
      vec4 b0=vec4(x.xy,y.xy); vec4 b1=vec4(x.zw,y.zw);
      vec4 s0=floor(b0)*2.+1.; vec4 s1=floor(b1)*2.+1.; vec4 sh=-step(h,vec4(0.));
      vec4 a0=b0.xzyw+s0.xzyw*sh.xxyy; vec4 a1=b1.xzyw+s1.xzyw*sh.zzww;
      vec3 p0=vec3(a0.xy,h.x); vec3 p1=vec3(a0.zw,h.y); vec3 p2=vec3(a1.xy,h.z); vec3 p3=vec3(a1.zw,h.w);
      vec4 norm=taylorInvSqrt(vec4(dot(p0,p0),dot(p1,p1),dot(p2,p2),dot(p3,p3)));
      p0*=norm.x; p1*=norm.y; p2*=norm.z; p3*=norm.w;
      vec4 m=max(.6-vec4(dot(x0,x0),dot(x1,x1),dot(x2,x2),dot(x3,x3)),0.); m=m*m;
      return 42.*dot(m*m,vec4(dot(p0,x0),dot(p1,x1),dot(p2,x2),dot(p3,x3)));
    }`;
  const mat = new THREE.ShaderMaterial({
    uniforms, transparent: true,
    vertexShader: noise + `
      uniform float uTime; uniform float uAmp; uniform vec2 uMouse; uniform float uHover;
      varying vec3 vN; varying vec3 vView; varying float vD;
      float disp(vec3 p){ return snoise(p * 1.1 + vec3(uTime * .25, uTime * .18, 0.)) * (uAmp + uHover * .12); }
      void main(){
        vec3 p = position;
        float d = disp(normalize(p));
        vec3 np = p + normal * d;
        // approximate normal from neighbours
        vec3 t = normalize(cross(normal, vec3(0.,1.,.001)));
        vec3 bt = normalize(cross(normal, t));
        float e = .02;
        vec3 pa = normalize(p + t * e); vec3 pb = normalize(p + bt * e);
        vec3 na = pa * length(p) + pa * disp(pa);
        vec3 nb = pb * length(p) + pb * disp(pb);
        vec3 nn = normalize(cross(na - np, nb - np));
        if (dot(nn, normal) < 0.) nn = -nn;
        vN = normalize(normalMatrix * nn);
        vec4 mv = modelViewMatrix * vec4(np, 1.);
        vView = normalize(-mv.xyz);
        vD = d;
        gl_Position = projectionMatrix * mv;
      }`,
    fragmentShader: `
      uniform float uTime;
      varying vec3 vN; varying vec3 vView; varying float vD;
      vec3 pal(float t){
        vec3 pink = vec3(1., .56, .76), lav = vec3(.66, .58, 1.), sky = vec3(.49, .78, 1.), mint = vec3(.56, .92, .78);
        t = fract(t);
        if (t < .25) return mix(pink, lav, t * 4.);
        if (t < .5) return mix(lav, sky, (t - .25) * 4.);
        if (t < .75) return mix(sky, mint, (t - .5) * 4.);
        return mix(mint, pink, (t - .75) * 4.);
      }
      void main(){
        float fres = pow(1. - max(dot(vN, vView), 0.), 2.2);
        float t = vN.y * .35 + vN.x * .25 + vD * .8 + uTime * .05;
        vec3 col = pal(t);
        col = mix(col, vec3(1.), fres * .75);                       // glassy rim
        float spec = pow(max(dot(reflect(-normalize(vec3(-.4,.8,.6)), vN), vView), 0.), 40.);
        col += spec * .6;                                            // highlight
        gl_FragColor = vec4(col, .92);
      }`
  });
  const blob = new THREE.Mesh(new THREE.IcosahedronGeometry(1.35, 48), mat);
  scene.add(blob);

  const resize = () => {
    const s = canvas.clientWidth;
    renderer.setSize(s, s, false);
  };
  new ResizeObserver(resize).observe(canvas); resize();

  let mx = 0, my = 0, hover = 0;
  addEventListener("pointermove", (e) => {
    mx = e.clientX / innerWidth - .5; my = e.clientY / innerHeight - .5;
    const r = canvas.getBoundingClientRect();
    const dx = e.clientX - (r.left + r.width / 2), dy = e.clientY - (r.top + r.height / 2);
    hover = Math.hypot(dx, dy) < r.width * .3 ? 1 : 0;
  }, { passive: true });

  let visible = true;
  new IntersectionObserver(([e]) => { visible = e.isIntersecting; }).observe(canvas);
  const clock = new THREE.Clock();
  const loop = () => {
    requestAnimationFrame(loop);
    const dt = Math.min(clock.getDelta(), .05);
    if (!visible) return;
    if (!reduce) uniforms.uTime.value += dt;
    uniforms.uHover.value += (hover - uniforms.uHover.value) * .05;
    blob.rotation.y += ((mx * .8) - blob.rotation.y) * .04 + (reduce ? 0 : dt * .05);
    blob.rotation.x += ((my * .6) - blob.rotation.x) * .04;
    const sp = Math.min(scrollY / innerHeight, 1);
    blob.scale.setScalar(1 - sp * .35);
    blob.position.y = sp * 1.2;
    renderer.render(scene, camera);
  };
  loop();
})();

/* Embedded resume PDF so "Download resume" works anywhere (local file or hosted). */
window.RESUME_PDF_B64 = "";